// ===========================================================================
// NAME / SLUG HANDLING
// ===========================================================================

/** 'The Nilgiris' -> 'the-nilgiris' */
function slugify(name) {
  return String(name)
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

/** 'kanniyakumari' -> 'Kanniyakumari', 'the-nilgiris' -> 'The Nilgiris' */
function humanize(slug) {
  return String(slug)
    .split('-')
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

// ===========================================================================
// GENERATED CONTENT — used for any city without a CURATED entry
// ===========================================================================
// Every string here is a function of the city name, so a new city arrives
// fully written. Where you have something genuinely local to say about a
// city, add a CURATED entry instead: unique copy is what separates a real
// location page from a doorway page in Google's eyes.

function buildDefaults(slug, name) {
  return {
    slug,
    district: name,
    state: 'Tamil Nadu',

    seo: {
      title: `Website Design Company in ${name} | Web Designer in ${name}`,
      description: `Engineered web systems for ${name} enterprises. Premium Next.js apps, fluid WhatsApp automation, custom branding, and localized conversion optimization maps.`,
      keywords: [
        `website design company in ${name}`,
        `web development company ${name}`,
        `digital marketing agency ${name}`,
        `gmb optimization ${name}`,
        `app developers ${name}`,
        `meta ads expert ${name}`,
      ],
      ogImage: '/og/og-image.png',
    },

    hero: {
      headline: `Website Design Company in ${name}`,
      subheadline: `Boost your online reach with custom blog website development in ${name}, engineered for speed, reader retention, and top Google rankings. We build fast, mobile-first blogging platforms equipped with schema markup, clean URL architecture, and seamless content management — helping businesses, creators, and publishers turn organic search traffic into loyal audiences.`,
      cta: 'Get a Free Website Audit',
    },

    // Rendered by <Faq items={...}> AND used to build the FAQPage schema, so
    // the two can never disagree. Google requires FAQ schema content to be
    // visible on the page; generating both from one array enforces that.
    faq: [
      {
        q: `How long does it take to build a website for a business in ${name}?`,
        a: 'Core Next.js platforms are engineered and deployed within 7 to 14 business days. Larger e-commerce systems with custom dashboards scale to 21-45 days depending on the operational logic involved.',
      },
      {
        q: `Will my website rank on Google for searches in ${name}?`,
        a: `Every build ships with local SEO in place — Google Business Profile setup, ${name}-specific schema markup, XML sitemaps, and semantic HTML — so you compete for local searches from day one rather than waiting on a separate SEO project.`,
      },
      {
        q: `Do you work with small businesses in ${name} or only large companies?`,
        a: `We build for both. A single-location shop in ${name} gets a fast, focused site sized to its needs; larger firms get multi-page platforms with custom dashboards. Pricing is fixed and quoted upfront either way.`,
      },
      {
        q: 'How does WhatsApp automation help my business?',
        a: 'Instead of enquiries getting lost in an email inbox, we wire direct WhatsApp routing into the site. High-intent visitors land straight in your chat feed, where labels let you separate hot leads from routine support.',
      },
      {
        q: `Can you migrate my existing ${name} business website to Next.js?`,
        a: 'Yes. We rebuild slow legacy platforms — WordPress, Wix, and basic site builders — into fast Next.js apps, carrying over your content and link architecture so existing Google rankings survive the move.',
      },
      {
        q: 'What happens after the site goes live?',
        a: 'Every package includes a priority monitoring period after launch. Beyond that the serverless architecture runs maintenance-free, and optional monthly retainers cover ongoing feature and layout work.',
      },
    ],
  };
}

// ===========================================================================
// GEO — approximate district-centre coordinates
// ===========================================================================
// Used for geo meta tags and LocalBusiness schema, both of which are hints
// rather than precise addresses. A city with no entry here simply renders
// without geo tags — that is deliberate. Wrong coordinates are worse than
// none, so add real ones (or a `geo` key on the CITIES entry) instead of
// letting a city inherit somebody else's location.
export const districtGeo = {
  chennai: { lat: 13.0827, lng: 80.2707 },
  coimbatore: { lat: 11.0168, lng: 76.9558 },
  madurai: { lat: 9.9252, lng: 78.1198 },
  tiruchirappalli: { lat: 10.7905, lng: 78.7047 },
  salem: { lat: 11.6643, lng: 78.146 },
  theni: { lat: 10.0104, lng: 77.4777 },
};

// ===========================================================================
// THE MERGE — CITIES + CURATED -> the districts every page reads from
// ===========================================================================

const CURATED_BY_SLUG = new Map(CURATED.map((d) => [d.slug, d]));

function normalize(entry) {
  const isString = typeof entry === 'string';
  const name = isString ? humanize(slugify(entry)) : entry.name || humanize(entry.slug);
  const slug = isString ? slugify(entry) : entry.slug || slugify(entry.name);

  const defaults = buildDefaults(slug, name);
  const curated = CURATED_BY_SLUG.get(slug);
  const overrides = isString ? {} : entry;

  // Later sources win. `seo` is merged one level deeper so a CURATED entry
  // that sets only `title` still inherits the generated description.
  return {
    ...defaults,
    ...curated,
    ...overrides,
    slug,
    district: name,
    seo: { ...defaults.seo, ...curated?.seo, ...overrides.seo },
    hero: { ...defaults.hero, ...curated?.hero, ...overrides.hero },
    faq: overrides.faq || curated?.faq || defaults.faq,
  };
}

/** Every city page on the site, fully resolved. */
export const districts = CITIES.map(normalize);

// A city listed twice would silently produce two identical routes and a
// duplicate-content pair in the sitemap, so fail loudly at build time.
const seen = new Set();
for (const d of districts) {
  if (seen.has(d.slug)) {
    throw new Error(
      `districtsData: duplicate city slug "${d.slug}" in CITIES — each city may appear only once.`,
    );
  }
  seen.add(d.slug);
}

// ===========================================================================
// LOOKUPS
// ===========================================================================

const BY_SLUG = new Map(districts.map((d) => [d.slug, d]));

export function getDistrictBySlug(slug) {
  return BY_SLUG.get(slug) || null;
}

export function getAllDistrictSlugs() {
  return districts.map((d) => d.slug);
}

/** Coordinates for a city, or null when we don't have real ones. */
export function getDistrictGeo(slug) {
  return getDistrictBySlug(slug)?.geo || districtGeo[slug] || null;
}

export const siteConfig = {
  companyName: COMPANY_NAME,
  domain: DOMAIN,
  phone: PHONE,
  email: EMAIL,
};

// ===========================================================================
// ROUTE HELPERS
// ===========================================================================
// Every city page lives at /website-design-company-in-{slug}. Next.js cannot
// express that as a folder — a dynamic segment must be the WHOLE segment
// (its own test is /\/\[[^/]+\](?=\/|$)/), so `website-design-company-in-[city]`
// would be read as a literal folder name. Instead the route is app/[citySlug]
// and the full path IS the param. These helpers keep the prefix in one place
// so the page, the sitemap and any internal links can never drift apart.

export const CITY_PATH_PREFIX = 'website-development-company-in-';

/** 'theni' -> 'website-design-company-in-theni' */
export function slugToCityPath(slug) {
  return `${CITY_PATH_PREFIX}${slug}`;
}

/** 'website-design-company-in-theni' -> district object, or null */
export function getDistrictByCityPath(citySlug) {
  if (typeof citySlug !== 'string' || !citySlug.startsWith(CITY_PATH_PREFIX)) {
    return null;
  }
  return getDistrictBySlug(citySlug.slice(CITY_PATH_PREFIX.length));
}

/** Every full path, for generateStaticParams() and the sitemap. */
export function getAllCityPaths() {
  return districts.map((d) => slugToCityPath(d.slug));
}
